export const GUIDES = [...CORE_GUIDES.map((guide) => ({ ...guide, published: guide.published || guide.updated, sources: CORE_SOURCES[guide.slug] || [], internalLinks: guide.slug === "prs-database-registration" ? [{ label: "2026 landlord timeline", url: "/guides/renters-rights-act-2026-landlord-timeline" }] : [{ label: "Free landlord calculators", url: "/tools" }] })), ...FOCUSED_GUIDES, ...SUPPORTING_GUIDES];

export function getGuide(slug) {
  return GUIDES.find((g) => g.slug === slug) || null;
}
